(()=>{const themes=['ink','paper','mint'];const labels={paper:'Paper',ink:'Ink',mint:'Mint'};let saved=localStorage.getItem('agentos-theme');if(saved==='dawn'||saved==='paper')saved='ink';let idx=Math.max(0,themes.indexOf(saved||'ink'));const apply=()=>{document.body.classList.remove(...themes.map(x=>'theme-'+x));document.body.classList.add('theme-'+themes[idx]);localStorage.setItem('agentos-theme',themes[idx]);const b=document.querySelector('[data-action="theme"]');if(b)b.innerHTML='<i></i> '+labels[themes[idx]]};apply();setTimeout(()=>{const top=document.querySelector('.top');if(top&&!top.querySelector('[data-action="theme"]'))top.insertAdjacentHTML('beforeend','<button class="top-btn theme-picker" data-action="theme"><i></i> Ink</button>')},80);document.addEventListener('click',e=>{const b=e.target.closest('[data-action="theme"]');if(!b)return;idx=(idx+1)%themes.length;apply();toast('Theme changed to '+labels[themes[idx]])})})();
