// Real MCP endpoint configuration: handshake happens server-side, never in the browser.
(function(){
 const labels={slack:'Slack MCP',gmail:'Gmail MCP',cal:'Cal.com MCP',github:'GitHub MCP',notion:'Notion MCP',drive:'Google Drive MCP'};
 function config(id){openModal(`<div class="hub-kicker">MCP SERVER / ${id.toUpperCase()}</div><h2>Connect ${labels[id]||id}</h2><p class="hub-copy">Paste the Streamable HTTP or HTTP JSON-RPC endpoint supplied by your MCP server. Your bearer token is sent only to the local AgentOS server.</p><div class="field"><label>MCP ENDPOINT URL</label><input id="mcpUrl" placeholder="https://your-server.example/mcp"></div><div class="field"><label>BEARER TOKEN (OPTIONAL)</label><input id="mcpToken" type="password" autocomplete="off" placeholder="Paste token"></div><div class="modal-actions"><button data-action="close">Cancel</button><button class="primary" data-action="save-mcp" data-mcp="${id}">Test & connect</button></div>`)}
 document.addEventListener('click',e=>{const b=e.target.closest('[data-action="toggle-integration"]');if(!b)return;e.preventDefault();e.stopImmediatePropagation();config(b.dataset.int)},true);
 document.addEventListener('click',async e=>{const b=e.target.closest('[data-action="save-mcp"]');if(!b)return;const url=$('#mcpUrl').value.trim(),token=$('#mcpToken').value.trim();if(!url)return toast('Enter an MCP endpoint URL');try{await api('/mcp/servers',{method:'POST',body:JSON.stringify({id:b.dataset.mcp,name:labels[b.dataset.mcp]||b.dataset.mcp,url,token})});closeModal();toast('MCP handshake succeeded and connector saved')}catch(err){toast(err.message)}});
})();
